using AssetForge.Core.Models;using AssetForge.Infrastructure.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;namespace AssetForge.Web.Pages;[AllowAnonymous]public class LookupModel(AssetForgeDbContext db):PageModel{public Asset? Asset{get;set;}public async Task OnGetAsync(string tag)=>Asset=await db.Assets.AsNoTracking().Include(x=>x.Category).Include(x=>x.Location).FirstOrDefaultAsync(x=>x.AssetTag==tag);}
